package com.decms.servlet;
import com.decms.util.*;import jakarta.servlet.*;import jakarta.servlet.http.*;import jakarta.servlet.annotation.*;import jakarta.servlet.*;import java.io.*;import java.sql.*;import java.security.*;import java.util.*;
@WebServlet("/evidence") @MultipartConfig(maxFileSize=10485760)
public class EvidenceServlet extends HttpServlet{
 protected void service(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{if(!Auth.protect(r,s))return;super.service(r,s);}
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try(Connection c=DB.getConnection();Statement st=c.createStatement();ResultSet rs=st.executeQuery("SELECT e.*,ca.case_no FROM evidence e JOIN cases ca ON ca.id=e.case_id ORDER BY e.id DESC")){r.setAttribute("rows",rs);r.getRequestDispatcher("/evidence.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{Part part=r.getPart("file");String original=part==null?null:part.getSubmittedFileName(),stored=null,hash=null;
 if(part!=null&&original!=null&&!original.isBlank()){String ext=original.contains(".")?original.substring(original.lastIndexOf('.')):"";stored=UUID.randomUUID()+ext;File dir=new File(getServletContext().getRealPath("/uploads"));if(!dir.exists())dir.mkdirs();part.write(new File(dir,stored).getAbsolutePath());try(InputStream in=new FileInputStream(new File(dir,stored))){MessageDigest md=MessageDigest.getInstance("SHA-256");byte[] b=new byte[8192];int n;while((n=in.read(b))>0)md.update(b,0,n);StringBuilder z=new StringBuilder();for(byte x:md.digest())z.append(String.format("%02x",x));hash=z.toString();}catch(Exception e){throw new ServletException(e);}}
 try(Connection c=DB.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO evidence(case_id,evidence_name,evidence_type,description,original_filename,stored_filename,sha256) VALUES(?,?,?,?,?,?,?)")){p.setInt(1,Integer.parseInt(r.getParameter("case_id")));p.setString(2,r.getParameter("evidence_name"));p.setString(3,r.getParameter("evidence_type"));p.setString(4,r.getParameter("description"));p.setString(5,original);p.setString(6,stored);p.setString(7,hash);p.executeUpdate();}catch(Exception e){throw new ServletException(e);}s.sendRedirect(r.getContextPath()+"/evidence");}
}
